-- Tallinn Tastebuds — the Google Places export, as SQL.
--
-- GENERATED by tools/googlevenues.mjs from exports/tallinn_restaurants.csv.
-- Do not edit: the next run overwrites it. Re-runnable, and safe to run
-- against a database that already holds an older copy of the export.
--
--   wrangler d1 execute tallinntastebuds         --remote --file=db/google-venues.sql
--   wrangler d1 execute tallinntastebuds-preview --remote --file=db/google-venues.sql
--
-- db/schema.sql has to have been applied first — it is what creates the
-- table these rows go into.
-- 751 places, 32 of them also on the map.

-- Everything is marked missing, and every upsert below clears the mark.
-- Whatever is still marked when this file finishes is genuinely no longer
-- in the export. Nothing is deleted: a list may be pointing at it.
UPDATE google_venues SET missing_since = CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE missing_since IS NULL;

